using Microsoft.AspNetCore.Mvc;
using ModelBindingValidation.Models;

namespace ModelBindingValidation.Controllers
{
    public class JobController : Controller
    {
        [HttpGet]
        public IActionResult Index() => View();

        [HttpPost]
        public IActionResult Index(JobApplication model)
        {
            if (string.IsNullOrEmpty(model.Name))
                ModelState.AddModelError(nameof(model.Name), "Please enter your name.");

            if (model.DOB == default(DateTime))
                ModelState.AddModelError(nameof(model.DOB), "Please enter your Date of Birth.");
            else if (model.DOB > DateTime.Now)
                ModelState.AddModelError(nameof(model.DOB), "Date of Birth cannot be in the future.");

            if (string.IsNullOrEmpty(model.Sex))
                ModelState.AddModelError(nameof(model.Sex), "Please select your sex.");

            if (model.Experience == "Select")
                ModelState.AddModelError(nameof(model.Experience), "Please select your experience level.");

            if (!model.TermsAccepted)
                ModelState.AddModelError(nameof(model.TermsAccepted), "You must accept the terms and conditions.");

            if (ModelState.IsValid)
                return View("Accepted", model);
            return View(model);
        }
    }
}

using System.ComponentModel.DataAnnotations;

namespace ModelBindingValidation.Models
{
    public class JobApplication
    {
        [Required(ErrorMessage = "Please enter your name.")]
        [Display(Name = "Full Name")]
        [StringLength(100, MinimumLength = 2,
            ErrorMessage = "Name must be 2–100 characters.")]
        public string Name { get; set; }

        [Required(ErrorMessage = "Please enter your Date of Birth.")]
        public DateTime DOB { get; set; }

        [Required(ErrorMessage = "Please select your sex.")]
        public string Sex { get; set; }

        [Range(0, 5, ErrorMessage = "Experience must be between 0 and 5.")]
        public int Experience { get; set; }

        [Range(typeof(bool), "true", "true",
            ErrorMessage = "You must accept the Terms & Conditions.")]
        public bool TermsAccepted { get; set; }

        [Required(ErrorMessage = "Email is required.")]
        [EmailAddress(ErrorMessage = "Please enter a valid email address.")]
        public string Email { get; set; }
    }
}

[HttpPost]
public IActionResult Index(JobApplication model)
{
    if (ModelState.IsValid)
    {
        // Complex business rule validations can go here
        if (model.Name == "Osama Bin Laden")
            ModelState.AddModelError(nameof(model.Name), "You cannot apply for the Job.");
        if (model.DOB > DateTime.Now)
            ModelState.AddModelError(nameof(model.DOB), "Date of Birth cannot be in the future.");
    }

    if (ModelState.IsValid)
        return View("Accepted", model);
    return View(model);
}

using System.ComponentModel.DataAnnotations;

namespace ModelBindingValidation.Infrastructure
{
    public class FutureDateValidator : ValidationAttribute
    {
        private readonly int _minYear;

        public FutureDateValidator(int minYear = 1980)
        {
            _minYear = minYear;
            ErrorMessage = $"Date must be between {_minYear} and today.";
        }

        protected override ValidationResult IsValid(object value, ValidationContext context)
        {
            if (value is not DateTime date)
                return new ValidationResult("Invalid date.");

            if (date > DateTime.Now)
                return new ValidationResult("Date of Birth cannot be in the future.");

            if (date.Year < _minYear)
                return new ValidationResult(ErrorMessage);

            return ValidationResult.Success;
        }
    }
}

public class JobApplication
{
    [Required]
    [Display(Name = "Full Name")]
    [StringLength(100)]
    public string Name { get; set; }

    [Required]
    [FutureDateValidator(1980)]
    public DateTime DOB { get; set; }

    [Required]
    public string Sex { get; set; }

    [Range(0, 5)]
    public int Experience { get; set; }

    [Range(typeof(bool), "true", "true",
        ErrorMessage = "You must accept the Terms & Conditions.")]
    public bool TermsAccepted { get; set; }

    [Required]
    [EmailAddress]
    public string Email { get; set; }
}

// Controller — the action that returns the validation result
public JsonResult ValidateDate(DateTime DOB)
{
    if (DOB > DateTime.Now)
        return Json("Date of Birth cannot be in the future.");
    if (DOB.Year < 1980)
        return Json("Date of Birth should not be before 1980.");
    return Json(true); // true means valid
}

